//! WP-3.1 parity + safety tests.
//!
//! Parity oracle (03_PHYSICS §5 CI table): Phase 0 `js/labs/logic` —
//! **identical truth tables, identical event order**. The golden fixtures in
//! `tests/fixtures/*.json` were generated by the real Phase 0 engine
//! (`tests/generate_fixtures.mjs`, which also registers JS mirrors of the
//! verified kernel cells so Q4 benches run through the actual oracle).
//! `cargo test` replays them element-by-element — no node required at test
//! time, the fixtures are committed engine output.

use crate::components::{BlockParams, ComponentKind};
use crate::engine::{run_logic, Block, EventRecord, LogicDiagram, PortRef, RunOptions, Wire};
use crate::radix::{Radix, RadixConstants};
use crate::truth_table::{truth_table, BoxedReferenceFn};
use crate::value::LogicValue;
use serde_json::Value;

fn fixture(name: &str) -> Value {
    let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures")
        .join(format!("{name}.json"));
    serde_json::from_str(&std::fs::read_to_string(path).expect("fixture exists"))
        .expect("fixture JSON")
}

/// Rebuild the oracle diagram from the fixture's recorded diagram section.
fn diagram_from_fixture(diagram: &Value, options: &Value) -> LogicDiagram {
    let radix =
        Radix::new(diagram["radix"].as_u64().expect("radix") as u32).expect("fixture radix");
    let mut blocks = Vec::new();
    for b in diagram["blocks"].as_array().expect("blocks") {
        let kind = ComponentKind::from_type_id(b["type"].as_str().expect("type"))
            .unwrap_or_else(|| panic!("unknown fixture type {}", b["type"]));
        let mut params = BlockParams::defaults_for(kind);
        // User overrides (defaults already applied by the oracle addBlock).
        if let Some(obj) = b["params"].as_object() {
            if let Some(v) = obj.get("value") {
                params.value = v.as_u64().expect("value") as u32;
            }
            if let Some(v) = obj.get("delay") {
                params.delay = v.as_u64().expect("delay");
            }
            if let Some(v) = obj.get("tco") {
                params.tco = v.as_u64().expect("tco");
            }
            if let Some(v) = obj.get("init") {
                params.init = v.as_u64().expect("init") as u32;
            }
            if let Some(v) = obj.get("period") {
                params.period = v.as_u64().expect("period");
            }
            if let Some(v) = obj.get("duty") {
                params.duty = v.as_f64().expect("duty");
            }
            if let Some(v) = obj.get("name") {
                params.name = Some(v.as_str().expect("name").to_string());
            }
        }
        blocks.push(Block {
            id: b["id"].as_str().expect("id").to_string(),
            kind,
            params,
        });
    }
    let mut wires = Vec::new();
    for w in diagram["wires"].as_array().expect("wires") {
        wires.push(Wire {
            from: PortRef {
                block: w["from"]["block"].as_str().expect("from.block").to_string(),
                port: w["from"]["port"].as_str().expect("from.port").to_string(),
            },
            to: PortRef {
                block: w["to"]["block"].as_str().expect("to.block").to_string(),
                port: w["to"]["port"].as_str().expect("to.port").to_string(),
            },
        });
    }
    let _ = options;
    LogicDiagram {
        radix,
        blocks,
        wires,
    }
}

fn fixture_test(name: &str) {
    let fx = fixture(name);
    let diagram = diagram_from_fixture(&fx["diagram"], &fx["options"]);
    let expected = &fx["expected"];
    let res = run_logic(
        &diagram,
        RunOptions {
            max_events: fx["options"]["maxEvents"].as_u64().unwrap_or(250_000),
            max_ticks: fx["options"]["maxTicks"].as_u64().unwrap_or(4000),
        },
    )
    .expect("fixture bench must not abort");

    // ok + problems + warnings — exact oracle strings, exact order.
    assert_eq!(res.ok, expected["ok"].as_bool().unwrap(), "{name}: ok");
    let problems: Vec<String> = expected["problems"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_str().unwrap().to_string())
        .collect();
    assert_eq!(res.problems, problems, "{name}: problems");
    let warnings: Vec<String> = expected["warnings"]
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_str().unwrap().to_string())
        .collect();
    assert_eq!(
        res.warnings, warnings,
        "{name}: warnings (exact oracle strings)"
    );

    // stats — identical event counts and end time.
    assert_eq!(
        res.stats.events,
        expected["stats"]["events"].as_u64().unwrap(),
        "{name}: stats.events"
    );
    assert_eq!(
        res.stats.max_time,
        expected["stats"]["maxTime"].as_u64().unwrap(),
        "{name}: stats.maxTime"
    );
    assert_eq!(
        res.stats.radix,
        expected["stats"]["radix"].as_u64().unwrap() as u32,
        "{name}: stats.radix"
    );

    // probes — identical change records (times + values + labels), keyed by
    // block id like the oracle.
    assert_eq!(
        res.probes.len(),
        expected["probes"].as_object().unwrap().len(),
        "{name}: probe count"
    );
    for (id, rec) in &res.probes {
        let p = &expected["probes"][id];
        assert!(p.is_object(), "{name}: probe {id} missing from oracle");
        let times: Vec<u64> = p["times"]
            .as_array()
            .unwrap()
            .iter()
            .map(|t| t.as_u64().unwrap())
            .collect();
        assert_eq!(&rec.times, &times, "{name}: probe {id} times");
        assert_eq!(
            rec.label,
            p["label"].as_str().unwrap(),
            "{name}: probe {id} label"
        );
        let values: Vec<Value> = p["values"].as_array().unwrap().to_vec();
        let got: Vec<Value> = rec
            .values
            .iter()
            .map(|v| serde_json::to_value(v).unwrap())
            .collect();
        assert_eq!(got, values, "{name}: probe {id} values (digit/Z encoding)");
    }

    // THE parity contract: identical event order, element by element.
    let oracle_events = expected["eventOrder"].as_array().expect("eventOrder");
    assert_eq!(
        res.events.len(),
        oracle_events.len(),
        "{name}: event stream length (identical event order)"
    );
    for (i, (got, want)) in res.events.iter().zip(oracle_events.iter()).enumerate() {
        let got_json = serde_json::to_value(got).expect("event serialization");
        assert_eq!(
            &got_json, want,
            "{name}: event {i} — identical event order vs Phase 0 engine"
        );
    }
}

