// ---- truth-table parity (exhaustive, vs independently-written refs) --------

#[test]
fn truth_tables_match_the_phase0_reference_across_binary_ternary_q4() {
    // The oracle's REF table (tests/core.test.mjs) — independently written.
    let r = |name: &str| -> BoxedReferenceFn {
        let f: BoxedReferenceFn = match name {
            "logic.AND" => Box::new(|d, _| vec![("y", LogicValue::Digit(d[0].min(d[1])))]),
            "logic.OR" => Box::new(|d, _| vec![("y", LogicValue::Digit(d[0].max(d[1])))]),
            "logic.NAND" => {
                Box::new(|d, r| vec![("y", LogicValue::Digit(r.max_digit() - d[0].min(d[1])))])
            }
            "logic.NOR" => {
                Box::new(|d, r| vec![("y", LogicValue::Digit(r.max_digit() - d[0].max(d[1])))])
            }
            "logic.XOR" => {
                Box::new(|d, r| vec![("y", LogicValue::Digit((d[0] + d[1]) % r.get() as u8))])
            }
            "logic.XNOR" => Box::new(|d, r| {
                vec![(
                    "y",
                    LogicValue::Digit(r.max_digit() - (d[0] + d[1]) % r.get() as u8),
                )]
            }),
            "logic.NOT" => Box::new(|d, r| vec![("y", LogicValue::Digit(r.max_digit() - d[0]))]),
            "logic.BUF" => Box::new(|d, _| vec![("y", LogicValue::Digit(d[0]))]),
            _ => unreachable!(),
        };
        f
    };
    for name in [
        "logic.AND",
        "logic.OR",
        "logic.NAND",
        "logic.NOR",
        "logic.XOR",
        "logic.XNOR",
        "logic.NOT",
        "logic.BUF",
    ] {
        for radix in [Radix::BINARY, Radix::TERNARY, Radix::Q4] {
            let kind = ComponentKind::from_type_id(name).unwrap();
            let t = truth_table(kind, radix, &r(name));
            assert!(t.pass, "{name} @ R={} truth-table parity", radix.get());
        }
    }
}

#[test]
fn addn_truth_table_matches_reference_arithmetic_for_all_radixes() {
    for radix in [
        Radix::BINARY,
        Radix::TERNARY,
        Radix::Q4,
        Radix::new(5).unwrap(),
        Radix::new(16).unwrap(),
    ] {
        let t = truth_table(ComponentKind::AddN, radix, &|d, r| {
            let s = d[0] + d[1] + d[2];
            vec![
                ("sum", LogicValue::Digit(s % r.get() as u8)),
                ("cout", LogicValue::Digit(s / r.get() as u8)),
            ]
        });
        assert!(t.pass, "ADDN @ R={}", radix.get());
    }
}

#[test]
fn q4_cells_match_the_verified_functions_exhaustively() {
    // q4_inv: Q_out = 3 − Q_in (03 equations + verified SPICE).
    let t = truth_table(ComponentKind::Q4Inv, Radix::Q4, &|d, _| {
        vec![("y", LogicValue::Digit(3 - d[0]))]
    });
    assert!(t.pass);
    // q4_half_adder: S = (A+B) mod 4, C = ⌊(A+B)/4⌋ (carry digit 0/1).
    let t = truth_table(ComponentKind::Q4HalfAdder, Radix::Q4, &|d, _| {
        let s = d[0] + d[1];
        vec![
            ("sum", LogicValue::Digit(s % 4)),
            ("carry", LogicValue::Digit(s / 4)),
        ]
    });
    assert!(t.pass);
    assert_eq!(t.total_rows, 16);
    // q4_mux4: out = d[sel] (verified candidate: .subckt q4_mux4 sel d0 d1 d2 d3 out).
    let t = truth_table(ComponentKind::Q4Mux4, Radix::Q4, &|d, _| {
        let data = [d[1], d[2], d[3], d[4]];
        if usize::from(d[0]) < 4 {
            vec![("y", LogicValue::Digit(data[usize::from(d[0])]))]
        } else {
            vec![("y", LogicValue::Z)]
        }
    });
    assert!(t.pass);
    // q4_thresh_det: identity at the logic level (analogue bridge in radix.rs).
    let t = truth_table(ComponentKind::Q4ThreshDet, Radix::Q4, &|d, _| {
        vec![("y", LogicValue::Digit(d[0]))]
    });
    assert!(t.pass);
}

#[test]
fn verified_q4_cell_functions_and_gate_counts_come_from_08_json() {
    let c = RadixConstants::embedded().expect("verified reference data");
    let inv = c.q4_cells.get("q4_inv").expect("q4_inv sealed");
    assert_eq!(inv.gates, 6);
    assert!(
        inv.function.contains("3"),
        "q4_inv documents Q_out = 3 − Q_in: {}",
        inv.function
    );
    let mux = c.q4_cells.get("q4_mux4").expect("q4_mux4 sealed");
    assert_eq!(mux.gates, 8);
    assert!(mux.function.contains("multiplexer"), "{}", mux.function);
    let ha = c
        .q4_cells
        .get("q4_half_adder")
        .expect("q4_half_adder sealed");
    assert_eq!(ha.gates, 8);
    assert!(ha.function.contains("mod 4"), "{}", ha.function);
    let td = c
        .q4_cells
        .get("q4_thresh_det")
        .expect("q4_thresh_det sealed");
    assert_eq!(td.gates, 6);
    assert!(td.function.contains("nearest"), "{}", td.function);
}

// ---- cycle / glitch / loop safety ------------------------------------------

fn not_loop_diagram() -> LogicDiagram {
    LogicDiagram {
        radix: Radix::BINARY,
        blocks: vec![
            Block {
                id: "IN".into(),
                kind: ComponentKind::In,
                params: BlockParams {
                    value: 0,
                    ..Default::default()
                },
            },
            Block {
                id: "NOT".into(),
                kind: ComponentKind::Not,
                params: BlockParams::default(),
            },
            Block {
                id: "P".into(),
                kind: ComponentKind::Probe,
                params: BlockParams::default(),
            },
        ],
        wires: vec![
            Wire {
                from: PortRef {
                    block: "IN".into(),
                    port: "out".into(),
                },
                to: PortRef {
                    block: "NOT".into(),
                    port: "a".into(),
                },
            },
            Wire {
                from: PortRef {
                    block: "NOT".into(),
                    port: "y".into(),
                },
                to: PortRef {
                    block: "NOT".into(),
                    port: "a".into(),
                },
            },
            Wire {
                from: PortRef {
                    block: "NOT".into(),
                    port: "y".into(),
                },
                to: PortRef {
                    block: "P".into(),
                    port: "in".into(),
                },
            },
        ],
    }
}

#[test]
fn combinational_loop_aborts_as_an_event_storm() {
    // NOT feeding itself on top of a driver — the oracle's oscillation case.
    let err = run_logic(
        &not_loop_diagram(),
        RunOptions {
            max_events: 2000,
            max_ticks: 4000,
        },
    )
    .unwrap_err();
    assert!(matches!(err, crate::engine::RunError::Oscillation { .. }));
    assert!(err
        .to_string()
        .contains("Event storm / oscillation detected"));
    assert!(err.to_string().contains("NOT gate feeding itself"));
}

#[test]
fn storm_aborts_are_bounded_by_max_events_deterministically() {
    // Any loop aborts at exactly max_events + 1 processed events — the cap is
    // honored deterministically (identical runs, identical abort points).
    for cap in [1000u64, 5000, 25_000] {
        let err = run_logic(
            &not_loop_diagram(),
            RunOptions {
                max_events: cap,
                max_ticks: 4000,
            },
        )
        .unwrap_err();
        assert!(
            matches!(err, crate::engine::RunError::Oscillation { max_events, .. } if max_events == cap)
        );
    }
}

#[test]
fn sequential_clock_cycles_terminate_inside_the_tick_budget() {
    // DFF + free-running clock is a CYCLE — must quiesce at maxTicks, no storm.
    let d = LogicDiagram {
        radix: Radix::BINARY,
        blocks: vec![
            Block {
                id: "D".into(),
                kind: ComponentKind::In,
                params: BlockParams {
                    value: 1,
                    ..Default::default()
                },
            },
            Block {
                id: "CLK".into(),
                kind: ComponentKind::Clock,
                params: BlockParams {
                    period: 100,
                    duty: 0.5,
                    ..Default::default()
                },
            },
            Block {
                id: "F".into(),
                kind: ComponentKind::Dff,
                params: BlockParams {
                    tco: 5,
                    init: 0,
                    ..Default::default()
                },
            },
            Block {
                id: "Q".into(),
                kind: ComponentKind::Probe,
                params: BlockParams {
                    name: Some("Q".into()),
                    ..Default::default()
                },
            },
        ],
        wires: vec![
            Wire {
                from: PortRef {
                    block: "D".into(),
                    port: "out".into(),
                },
                to: PortRef {
                    block: "F".into(),
                    port: "d".into(),
                },
            },
            Wire {
                from: PortRef {
                    block: "CLK".into(),
                    port: "out".into(),
                },
                to: PortRef {
                    block: "F".into(),
                    port: "clk".into(),
                },
            },
            Wire {
                from: PortRef {
                    block: "F".into(),
                    port: "q".into(),
                },
                to: PortRef {
                    block: "Q".into(),
                    port: "in".into(),
                },
            },
        ],
    };
    let res = run_logic(
        &d,
        RunOptions {
            max_events: 250_000,
            max_ticks: 400,
        },
    )
    .unwrap();
    assert!(res.ok);
    // Q init=0 is emitted at t=0 (probe records it), then Q samples D=1 at
    // the first rising edge (t=50, tco=5) and holds — oracle parity.
    let (_, rec) = &res.probes[0];
    assert_eq!(rec.values.first(), Some(&LogicValue::Digit(0)));
    assert_eq!(rec.times.first(), Some(&0));
    assert_eq!(rec.values.get(1), Some(&LogicValue::Digit(1)));
    assert_eq!(rec.times.get(1), Some(&55));
    // Finite clock schedule: bounded events, no storm.
    assert!(res.stats.events < 250_000);
}

#[test]
fn glitch_pulse_through_a_gate_chain_is_deterministic_and_bounded() {
    // A single-tick pulse from a clock with a 2-tick period through a chain
    // of delayed gates — every glitch edge is scheduled deterministically and
    // the run terminates (bounded by the clock window), never a storm.
    let d = LogicDiagram {
        radix: Radix::BINARY,
        blocks: vec![
            Block {
                id: "CLK".into(),
                kind: ComponentKind::Clock,
                params: BlockParams {
                    period: 2,
                    duty: 0.5,
                    ..Default::default()
                },
            },
            Block {
                id: "G1".into(),
                kind: ComponentKind::Buf,
                params: BlockParams {
                    delay: 1,
                    ..Default::default()
                },
            },
            Block {
                id: "G2".into(),
                kind: ComponentKind::Not,
                params: BlockParams {
                    delay: 1,
                    ..Default::default()
                },
            },
            Block {
                id: "P".into(),
                kind: ComponentKind::Probe,
                params: BlockParams::default(),
            },
        ],
        wires: vec![
            Wire {
                from: PortRef {
                    block: "CLK".into(),
                    port: "out".into(),
                },
                to: PortRef {
                    block: "G1".into(),
                    port: "a".into(),
                },
            },
            Wire {
                from: PortRef {
                    block: "G1".into(),
                    port: "y".into(),
                },
                to: PortRef {
                    block: "G2".into(),
                    port: "a".into(),
                },
            },
            Wire {
                from: PortRef {
                    block: "G2".into(),
                    port: "y".into(),
                },
                to: PortRef {
                    block: "P".into(),
                    port: "in".into(),
                },
            },
        ],
    };
    let res = run_logic(
        &d,
        RunOptions {
            max_events: 250_000,
            max_ticks: 400,
        },
    )
    .unwrap();
    assert!(res.ok, "glitch chain must terminate deterministically");
    // Deterministic: a second identical run produces the identical event stream.
    let res2 = run_logic(
        &d,
        RunOptions {
            max_events: 250_000,
            max_ticks: 400,
        },
    )
    .unwrap();
    assert_eq!(
        res.events, res2.events,
        "identical diagrams → identical runs"
    );
    assert_eq!(res.probes, res2.probes);
    // The inverted clock reaches the probe.
    let (_, rec) = &res.probes[0];
    assert!(
        rec.values.contains(&LogicValue::Digit(1)) && rec.values.contains(&LogicValue::Digit(0))
    );
}

#[test]
fn contention_is_detected_and_last_write_wins_by_event_order() {
    let d = LogicDiagram {
        radix: Radix::BINARY,
        blocks: vec![
            Block {
                id: "I1".into(),
                kind: ComponentKind::In,
                params: BlockParams {
                    value: 0,
                    ..Default::default()
                },
            },
            Block {
                id: "I2".into(),
                kind: ComponentKind::In,
                params: BlockParams {
                    value: 1,
                    ..Default::default()
                },
            },
            Block {
                id: "P".into(),
                kind: ComponentKind::Probe,
                params: BlockParams::default(),
            },
        ],
        wires: vec![
            Wire {
                from: PortRef {
                    block: "I1".into(),
                    port: "out".into(),
                },
                to: PortRef {
                    block: "P".into(),
                    port: "in".into(),
                },
            },
            Wire {
                from: PortRef {
                    block: "I2".into(),
                    port: "out".into(),
                },
                to: PortRef {
                    block: "P".into(),
                    port: "in".into(),
                },
            },
        ],
    };
    let res = run_logic(&d, RunOptions::default()).unwrap();
    assert_eq!(
        res.warnings,
        vec![
            "Block P: input \"in\" driven by 2 outputs — contention, result not meaningful."
                .to_string()
        ]
    );
    // Both driver events processed in (time, seq) order → last write wins.
    let (_, rec) = &res.probes[0];
    assert_eq!(rec.values, vec![LogicValue::Digit(0), LogicValue::Digit(1)]);
}

#[test]
fn z_propagation_and_unconnected_warning() {
    let d = LogicDiagram {
        radix: Radix::Q4,
        blocks: vec![
            Block {
                id: "ANDG".into(),
                kind: ComponentKind::And,
                params: BlockParams::default(),
            },
            Block {
                id: "PY".into(),
                kind: ComponentKind::Probe,
                params: BlockParams::default(),
            },
        ],
        wires: vec![Wire {
            from: PortRef {
                block: "ANDG".into(),
                port: "y".into(),
            },
            to: PortRef {
                block: "PY".into(),
                port: "in".into(),
            },
        }],
    };
    let res = run_logic(&d, RunOptions::default()).unwrap();
    assert_eq!(
        res.warnings,
        vec![
            "Block ANDG: input \"a\" unconnected (reads 'Z').".to_string(),
            "Block ANDG: input \"b\" unconnected (reads 'Z').".to_string()
        ]
    );
    let (_, rec) = &res.probes[0];
    assert_eq!(rec.values, vec![LogicValue::Z]);
}

